  static let all = categories.flatMap(\.emoji)

  // The five Fitzpatrick modifiers, light to dark.
  static let skinTones = (0x1F3FB...0x1F3FF).map { String(Unicode.Scalar($0)!) }

  // Whether the emoji takes a skin tone: a single person or hand, not a group joined with zero-width joiners.
  static func takesSkinTone(_ emoji: String) -> Bool {
    let scalars = Array(emoji.unicodeScalars)
    return scalars.first?.properties.isEmojiModifierBase == true && !scalars.contains { $0.value == 0x200D }
  }

  // The emoji in a skin tone, which replaces its text presentation selector.
  static func toned(_ emoji: String, _ tone: String) -> String {
    var scalars = Array(emoji.unicodeScalars)
    if scalars.count > 1, scalars[1].value == 0xFE0F {
      scalars.remove(at: 1)
    }
    scalars.insert(contentsOf: tone.unicodeScalars, at: 1)
    return String(String.UnicodeScalarView(scalars))
  }

  // What search matches: the Unicode names of its characters, or a flag's country.
  static func name(_ emoji: String) -> String {
    let scalars = emoji.unicodeScalars.filter(\.properties.isEmoji)
    guard scalars.allSatisfy({ (0x1F1E6...0x1F1FF).contains($0.value) }) else {
      return scalars.compactMap(\.properties.name).joined(separator: " ").lowercased()
    }
    let region = String(String.UnicodeScalarView(scalars.compactMap { Unicode.Scalar($0.value - 0x1F1A5) }))
    return ["flag", Locale.current.localizedString(forRegionCode: region)].compactMap { $0 }.joined(separator: " ").lowercased()
  }
